import{_ as n,C as l,o as c,c as a,j as t,a as o,E as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"字体配置与测试界面组件 (dev.anvilcraft.lib.v2.font.screen)","description":"","frontmatter":{},"headers":[],"relativePath":"26.1/font/screens.md","filePath":"26.1/font/screens.md"}'),s={name:"26.1/font/screens.md"};function f(g,e,b,v,p,h){const d=l("BranchContextCard");return c(),a("div",null,[e[0]||(e[0]=t("h1",{id:"字体配置与测试界面组件-dev-anvilcraft-lib-v2-font-screen",tabindex:"-1"},[o("字体配置与测试界面组件 ("),t("code",null,"dev.anvilcraft.lib.v2.font.screen"),o(") "),t("a",{class:"header-anchor",href:"#字体配置与测试界面组件-dev-anvilcraft-lib-v2-font-screen","aria-label":'Permalink to "字体配置与测试界面组件 (`dev.anvilcraft.lib.v2.font.screen`)"'},"​")],-1)),i(d,{branch:"26.1"}),e[1]||(e[1]=r('<p><code>dev.anvilcraft.lib.v2.font.screen</code> 与 <code>dev.anvilcraft.lib.v2.font.data</code> 包提供了 <code>anvillib_font</code> 模块内置的客户端字体选择界面（<code>FontConfigScreen</code>）、多样式渲染测试页（<code>FontTestScreen</code>）、支持遮挡屏蔽与滚动条拖拽的下拉框控件（<code>Dropdown</code>）以及界面语言数据生成器（<code>AnvilLibFontData</code>）。</p><p>这些类均标记为 <code>@ApiStatus.Internal</code>，玩家可通过 NeoForge 模组菜单选中 <code>AnvilLib Font</code> 点击“Config”直接进入该界面切换全局 SDF 渲染字体。</p><hr><h2 id="一、-界面组件结构与交互流程" tabindex="-1">一、 界面组件结构与交互流程 <a class="header-anchor" href="#一、-界面组件结构与交互流程" aria-label="Permalink to &quot;一、 界面组件结构与交互流程&quot;">​</a></h2><ol><li><strong><code>FontConfigScreen</code>（字体配置主界面）</strong>： <ul><li>顶栏实时使用 <code>guiGraphics.anvillib$centeredText(AnvilLibFont.getSelectFont(), ...)</code> 渲染当前选中的字体族与具体字重名称，所见即所得；</li><li>提供两个联动 <code>Dropdown</code> 下拉框：选择上方“字体族（Font Family）”下拉框后，会自动调用 <code>FontManager.INSTANCE.getFamilyFontNames(family)</code> 刷新下方“具体字体（Font）”下拉框的候选列表，并立即通过 <code>AnvilLibFont.CONFIG.setFontFamily</code> / <code>setFont</code> 写入 <code>config/anvillib/anvillib_font-client.json</code>；</li><li>点击上方 <code>Font Test</code> 按钮可打开 <code>FontTestScreen</code>。</li></ul></li><li><strong><code>FontTestScreen</code>（多语种多样式测试页）</strong>： <ul><li>使用当前选定的 SDF 字体集中展示 10 行涵盖简体中文、繁体中文、英文、日文假名、数字与标点符号的测试文本，分别验证红色/绿色/暗紫色、粗体（<code>withBold</code>）、斜体（<code>withItalic</code>）、粗斜体、下划线（<code>withUnderlined</code>）、删除线（<code>withStrikethrough</code>）以及动态随机字符混淆（<code>withObfuscated</code>）的渲染表现。</li></ul></li><li><strong><code>Dropdown</code>（带遮挡屏蔽区域的滚动下拉框控件）</strong>： <ul><li>当页面上上下排列多个 <code>Dropdown</code> 时，上方展开的下拉列表会覆盖在下方 <code>Dropdown</code> 之上。<code>Dropdown</code> 通过 <code>Dropdown.Shielding(x1, y1, x2, y2, dropdown)</code> 矩形屏蔽区机制通知父界面：当上方下拉框展开时，被其下拉菜单矩形遮挡的其他 <code>Dropdown</code> 在 <code>isMouseOver</code> 中会自动返回 <code>false</code>，防止点击展开项时穿透触发下层控件。</li></ul></li></ol><hr><h2 id="二、-类与-api-汇总表-apistatus-internal" tabindex="-1">二、 类与 API 汇总表（<code>@ApiStatus.Internal</code>） <a class="header-anchor" href="#二、-类与-api-汇总表-apistatus-internal" aria-label="Permalink to &quot;二、 类与 API 汇总表（`@ApiStatus.Internal`）&quot;">​</a></h2><h3 id="_1-fontconfigscreen-与-fonttestscreen" tabindex="-1">1. <code>FontConfigScreen</code> 与 <code>FontTestScreen</code> <a class="header-anchor" href="#_1-fontconfigscreen-与-fonttestscreen" aria-label="Permalink to &quot;1. `FontConfigScreen` 与 `FontTestScreen`&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类名</th><th style="text-align:left;">构造器与核心方法</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>FontConfigScreen</code></td><td style="text-align:left;"><code>public FontConfigScreen(final ModContainer ignored, final Screen parent)</code></td><td style="text-align:left;">由 <code>AnvilLibFont</code> 通过 <code>IConfigScreenFactory</code> 注册到 <code>ModContainer</code>。管理字体族下拉框、具体字体下拉框与测试页跳转按钮。</td></tr><tr><td style="text-align:left;"><code>FontTestScreen</code></td><td style="text-align:left;"><code>protected FontTestScreen(final Screen parent)</code></td><td style="text-align:left;">渲染 10 行不同 <code>Style</code> 组合的中英日繁及特殊符号 SDF 测试文本，按 <code>ESC</code> 关闭时返回 <code>FontConfigScreen</code>。</td></tr></tbody></table><h3 id="_2-dropdown-dev-anvilcraft-lib-v2-font-screen-widget-dropdown" tabindex="-1">2. <code>Dropdown</code>（<code>dev.anvilcraft.lib.v2.font.screen.widget.Dropdown</code>） <a class="header-anchor" href="#_2-dropdown-dev-anvilcraft-lib-v2-font-screen-widget-dropdown" aria-label="Permalink to &quot;2. `Dropdown`（`dev.anvilcraft.lib.v2.font.screen.widget.Dropdown`）&quot;">​</a></h3><p>继承自 <code>net.minecraft.client.gui.components.AbstractWidget</code>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">构造器 / 方法 / 内部记录签名</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public Dropdown(int x, int y, int width, int height, int screenWidth, int screenHeight, Component message)</code></td><td style="text-align:left;">构造下拉框控件，传入屏幕宽高以计算展开列表的最大可用高度。</td></tr><tr><td style="text-align:left;"><code>public void setAllow(List&lt;DropdownEntry&gt; allows)</code></td><td style="text-align:left;">设置下拉候选条目列表，重置滚动偏移 <code>scrollOffset = 0</code>；若原选中值不在新列表中，自动选中第一项（列表为空则置为 <code>null</code>）。</td></tr><tr><td style="text-align:left;"><code>public void setValue(@Nullable DropdownEntry value)</code> / <code>setValue(@Nullable String value)</code></td><td style="text-align:left;">按 <code>DropdownEntry</code> 或字符串 <code>id</code> 设置当前选中项（不会触发 <code>onValueChanged</code> 回调）。</td></tr><tr><td style="text-align:left;"><code>public @Nullable DropdownEntry getValue()</code> / <code>public @Nullable String getValueId()</code></td><td style="text-align:left;">获取当前选中的 <code>DropdownEntry</code> 或其字符串 <code>id</code>。</td></tr><tr><td style="text-align:left;"><code>public void setOnValueChanged(Consumer&lt;@Nullable DropdownEntry&gt; callback)</code></td><td style="text-align:left;">设置用户点击切换下拉选项时的回调。</td></tr><tr><td style="text-align:left;"><code>public void setOnShieldingAdd(Consumer&lt;Shielding&gt;)</code> / <code>setOnShieldingRemove(Runnable)</code> / <code>setShieldingGetter(Supplier&lt;@Nullable Shielding&gt;)</code></td><td style="text-align:left;">绑定展开列表遮挡屏蔽区的注册、移除与查询回调，防止多个下拉框上下叠放时发生鼠标点击穿透。</td></tr><tr><td style="text-align:left;"><code>public int calcMaxHeight()</code></td><td style="text-align:left;">计算展开列表在屏幕底部剩余空间内的最大高度（向下取整为行高 <code>getHeight()</code> 的整数倍，避免底部出现残缺半行）。</td></tr><tr><td style="text-align:left;"><code>public record DropdownEntry(Component desc, String id)</code></td><td style="text-align:left;">下拉选项数据记录。提供 <code>DropdownEntry.create(String id)</code>（使用翻译键 <code>dropdown.anvillib_font.&lt;id&gt;</code>）与 <code>DropdownEntry.create(String desc, String id)</code>（使用字面量 <code>Component.literal(desc)</code>）两个静态工厂。</td></tr><tr><td style="text-align:left;"><code>public record Shielding(double x1, double y1, double x2, double y2, Dropdown dropdown)</code></td><td style="text-align:left;">记录展开列表占用的屏幕矩形区域。<code>isShielding(x, y, dropdown)</code> 对非自身的其他下拉框返回坐标是否落入屏蔽矩形内。</td></tr></tbody></table><h3 id="_3-anvillibfontdata-dev-anvilcraft-lib-v2-font-data-anvillibfontdata" tabindex="-1">3. <code>AnvilLibFontData</code>（<code>dev.anvilcraft.lib.v2.font.data.AnvilLibFontData</code>） <a class="header-anchor" href="#_3-anvillibfontdata-dev-anvilcraft-lib-v2-font-data-anvillibfontdata" aria-label="Permalink to &quot;3. `AnvilLibFontData`（`dev.anvilcraft.lib.v2.font.data.AnvilLibFontData`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">类 / 方法签名</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>public class AnvilLibFontData</code> / <code>public static class AnvilLibFontLanguageProvider extends LanguageProvider</code></td><td style="text-align:left;">监听 <code>anvillib_font</code> 的 <code>GatherDataEvent.Client</code>，生成配置界面与下拉框无障碍朗读所需的 6 个英文翻译键（<code>screen.anvillib_font.config</code>、<code>screen.anvillib_font.config.family</code>、<code>screen.anvillib_font.config.font</code>、<code>screen.anvillib_font.config.test</code>、<code>narration.anvillib_font.dropdown.expanded</code>、<code>narration.anvillib_font.dropdown.collapsed</code>）。</td></tr></tbody></table>',14))])}const x=n(s,[["render",f]]);export{y as __pageData,x as default};
